insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('supply', 'advanced', 'module', 'm01-one-cargo-every-way', 1, 'cargoQuantities is called on the invented BADAGRY cargo with its quantity and unit given and the density left out. What does the engine return?', '["REFUSED: Cargo quantity is required.", "The cargo converted at the petrol density of 745 kg/m3 that PRODUCT_REFERENCE lists for PMS.", "REFUSED: Density is required to convert between mass and volume; it is not assumed.", "REFUSED: Unknown quantity unit \"kg\"."]'::jsonb, 2, 'Every volume the function forms needs the density, so with none supplied it forms nothing and names the density as the missing input.'),
  ('supply', 'advanced', 'module', 'm01-one-cargo-every-way', 2, 'The invented BADAGRY cargo is entered as 34000 with the unit typed as kg and its density of 742.8 kg/m3 given. Which answer does cargoQuantities give?', '["REFUSED: Unknown quantity unit \"kg\".", "A cargo of 34000 tonnes, because the engine maps a mass unit it does not list to the nearest mass unit it does.", "REFUSED: Density is required to convert between mass and volume; it is not assumed.", "REFUSED: Cargo quantity is required."]'::jsonb, 0, 'The digest prints this row as REFUSED: Unknown quantity unit "kg". The cargo table converts entries in tonne, m3, litre and bbl, and kg is none of them, so the row returns no figure.'),
  ('supply', 'advanced', 'module', 'm01-one-cargo-every-way', 3, 'A quantity of zero is put to cargoQuantities with a valid unit and the density of 742.8 kg/m3. What comes back?', '["An empty cargo in every unit, since a zero quantity is still a quantity the rules can convert.", "REFUSED: Density is required to convert between mass and volume; it is not assumed.", "REFUSED: Unknown quantity unit \"kg\".", "REFUSED: Cargo quantity is required."]'::jsonb, 3, 'The digest prints the zero quantity case as the refusal "Cargo quantity is required." The engine forms no volume for a cargo it has not been given.'),
  ('supply', 'advanced', 'module', 'm01-one-cargo-every-way', 4, '34000 tonnes of the invented BADAGRY petrol cargo are entered at its certificate density of 742.8 kg/m3. How many cubic metres does the engine return?', '["45637.584 m3", "45772.752 m3", "45772.700 m3", "45772.442 m3"]'::jsonb, 1, 'm3 = tonnes x 1000 / density gives 45772.752 m3. 45637.584 m3 is the same tonnes at the reference density of 745 kg/m3, and the other two are the rows typed as 45772.7 m3 and as 287900 bbl.'),
  ('supply', 'advanced', 'module', 'm01-one-cargo-every-way', 5, 'BADAGRY is entered as 45772.7 m3 at 742.8 kg/m3 and comes back as 33999.9616 tonnes. Why does the tonne figure not read 34000.0000?', '["The barrel constant of 0.158987294928 is itself rounded, so every trip through a volume sheds a little mass.", "The engine stores litres to two decimals and rebuilds the tonnes from that stored litre figure.", "The typed 45772.7 m3 is short of the cargo''s 45772.752 m3, and the engine converts it as typed.", "The density of 742.8 kg/m3 is applied at the observed temperature when the entry is a volume."]'::jsonb, 2, 'm3 = tonnes x 1000 / density, so the engine forms tonnes from the volume it is handed. 34000 tonnes at 742.8 kg/m3 is 45772.752 m3, and the 45772.7 m3 typed converts to 33999.9616 tonnes.'),
  ('supply', 'advanced', 'module', 'm01-one-cargo-every-way', 6, 'A BADAGRY entry of 287900 bbl, density 742.8 kg/m3, comes back from cargoQuantities in tonnes as what?', '["33999.7701 tonnes", "33999.9616 tonnes", "34000.0000 tonnes", "45772.442 tonnes"]'::jsonb, 0, 'The 287900 bbl row reads 45772.442 m3 and 33999.7701 tonnes. 34000.0000 tonnes is the row entered in tonnes, 33999.9616 tonnes the rows entered as 45772.7 m3 and as 45772700 litres, and 45772.442 is the barrel row''s volume in m3.'),
  ('supply', 'advanced', 'module', 'm01-one-cargo-every-way', 7, '34000 tonnes are run through cargoQuantities at the kerosene density of 800 kg/m3 that PRODUCT_REFERENCE lists for DPK. What comes back?', '["40476.190 m3 and 40476190.48 litres", "45637.584 m3 and 45637583.89 litres", "45772.752 m3 and 45772751.75 litres", "42500.000 m3 and 42500000.00 litres"]'::jsonb, 3, 'The density rows read 42500.000 m3 and 42500000.00 litres for DPK at 800 kg/m3. 40476.190 m3 is the AGO row at 840 kg/m3, 45637.584 m3 the PMS row at 745 kg/m3, and 45772.752 m3 the BADAGRY cargo at its own 742.8 kg/m3.'),
  ('supply', 'advanced', 'module', 'm01-one-cargo-every-way', 8, 'The same 34000 tonnes are run at 742.8 kg/m3 and at the petrol reference density of 745 kg/m3. What does the pair of results show?', '["Both densities are petrol, so the engine returns 45772.752 m3 for each and the reference figure is harmless.", "A density inside the petrol range can still describe a different cargo on paper: 45772.752 m3 against 45637.584 m3.", "The reference density is rejected because it falls outside the petrol range the module lists.", "The two volumes agree to the litre once each is expressed in barrels through the constant 0.158987294928."]'::jsonb, 1, 'Both are petrol densities in PRODUCT_REFERENCE, yet the engine returns 45772.752 m3 at 742.8 kg/m3 and 45637.584 m3 at 745 kg/m3. The certificate of quality is the authority, which is why the cargo''s own figure is the one typed.'),
  ('supply', 'advanced', 'module', 'm01-one-cargo-every-way', 9, 'The invented BADAGRY cargo is entered once as 45772.7 m3 and once as 45772700 litres, both at 742.8 kg/m3. What do the two entries return?', '["The same figures: 45772.700 m3, 33999.9616 tonnes and 287901.6215 barrels.", "The litre entry refused, since litres are not a unit the cargo table converts.", "The same m3, with 34000.0000 tonnes on the litre entry.", "Two m3 figures 1000 apart, since the litre entry is read as m3."]'::jsonb, 0, 'The two rows print alike: 45772.700 m3, 45772700.00 litres, 33999.9616 tonnes and 287901.6215 barrels. litres = m3 x 1000, so the two entries are one quantity.'),
  ('supply', 'advanced', 'module', 'm01-one-cargo-every-way', 10, 'Two barrel figures for the invented BADAGRY cargo at 742.8 kg/m3 disagree: 287900.0000 and 287901.9470. What differs between the two rows?', '["The barrel constant, which each row carries to a different number of decimals.", "The litre count, which one row rounds to two decimals before it forms the barrels.", "The quantity typed: 287900 bbl in one row and 34000 tonnes in the other.", "The density, 742.8 kg/m3 in one row and 745 kg/m3 in the other."]'::jsonb, 2, 'Both rows are the BADAGRY cargo at 742.8 kg/m3. The 287900 bbl row returns 287900.0000 barrels and the 34000 tonne row 287901.9470, and barrels = m3 / 0.158987294928 with one constant for every row.'),
  ('supply', 'advanced', 'module', 'm01-one-cargo-every-way', 11, 'How does cargoQuantities reach the barrel figure of 287901.9470 for 34000 tonnes at 742.8 kg/m3?', '["It multiplies the tonnes by a barrels-per-tonne factor held for each product in PRODUCT_REFERENCE.", "It divides the 45772751.75 litres by 1000 and then by the typical petrol density of 745 kg/m3.", "It divides the tonnes by 0.158987294928 and then corrects the result with the density of 742.8 kg/m3.", "It forms 45772.752 m3 through the density, then divides by 0.158987294928."]'::jsonb, 3, 'The engine never reaches a barrel from tonnes directly. The density gives the m3, 45772.752, and dividing by M3_PER_BBL, 0.158987294928, gives the barrels.'),
  ('supply', 'advanced', 'module', 'm01-one-cargo-every-way', 12, 'In IMPORT_TEMPLATE, which basis does the Marine insurance line ship with?', '["percent_of_cif", "percent_of_cf", "percent_of_fob", "per_tonne"]'::jsonb, 1, 'The template ships insurance as percent_of_cf. Import duty and Financing and letter of credit are the lines shipped on percent_of_cif, and freight and port are per_tonne.'),
  ('supply', 'advanced', 'module', 'm01-one-cargo-every-way', 13, 'Which of these bases belongs to PRICE_ELEMENT_BASIS and appears nowhere in CHARGE_BASIS?', '["percent_of_cif", "per_litre", "percent_of_running", "per_cargo"]'::jsonb, 2, 'CHARGE_BASIS carries per_tonne, per_m3, per_litre, per_bbl, per_cargo, percent_of_fob, percent_of_cf and percent_of_cif. PRICE_ELEMENT_BASIS carries per_litre, percent_of_landed and percent_of_running, so per_litre is in both lists.'),
  ('supply', 'advanced', 'module', 'm01-one-cargo-every-way', 14, 'Every line in IMPORT_TEMPLATE and PUMP_TEMPLATE ships its rate as none. What does RATE_DISCLAIMER tell the user to do with each rate?', '["Confirm it against the regulation in force.", "Use the template rate until a regulation is published.", "Read it from the oracles'' golden files.", "Take a missing rate as zero and name it."]'::jsonb, 0, 'RATE_DISCLAIMER ends "Confirm each against the regulation in force." The templates ship every rate as none, and the fuelpricing golden file ships none either, since every rate in it is synthetic.'),
  ('supply', 'advanced', 'module', 'm01-one-cargo-every-way', 15, 'Which pair of IMPORT_TEMPLATE lines ships with the basis percent_of_cif?', '["Marine insurance, and Import duty.", "Ocean freight, and Port and harbour charges.", "Jetty throughput and discharge, and Storage and handling.", "Import duty, and Financing and letter of credit."]'::jsonb, 3, 'Two landed lines bite on CIF in the template: Import duty and Financing and letter of credit. The insurance line itself ships on C&F, which is why it cannot be one of them.'),
  ('supply', 'advanced', 'module', 'm02-the-landed-cost-walk', 1, 'A user types the ocean freight line as a percent of CIF on the invented BADAGRY build-up. What does landedCost return?', '["REFUSED: Customs processing has an unknown stage \"customs\".", "REFUSED: The insurance rates on CIF add up to 100 percent or more.", "REFUSED: Ocean freight is a percentage of a value that is not formed until after freight.", "REFUSED: An FOB price and its basis are required."]'::jsonb, 2, 'Freight belongs to the freight stage, and CIF is formed at the insurance stage, after freight. The engine refuses a freight line that names a value formed later, and prints the same sentence for freight on C&F.'),
  ('supply', 'advanced', 'module', 'm02-the-landed-cost-walk', 2, 'A charge is added to the invented BADAGRY walk with its stage typed as "customs". Which answer does landedCost give?', '["The line is placed in the landed stage, the nearest stage the walk knows, and billed on CIF.", "REFUSED: Customs processing has an unknown stage \"customs\".", "REFUSED: Ocean freight is a percentage of a value that is not formed until after freight.", "REFUSED: The insurance rates on CIF add up to 100 percent or more."]'::jsonb, 1, 'The walk knows the stages freight, insurance and landed. A line with any other stage has no place in the order and so no frozen base, and the engine does not guess that customs means landed.'),
  ('supply', 'advanced', 'module', 'm02-the-landed-cost-walk', 3, 'Insurance is quoted on CIF at 100 percent in a test of the invented BADAGRY walk. What happens?', '["The closed form divides by zero and the engine prints a CIF of none beside a complete build-up.", "REFUSED: Ocean freight is a percentage of a value that is not formed until after freight.", "The engine moves the insurance onto C&F, the basis the template ships, and completes the walk.", "REFUSED: The insurance rates on CIF add up to 100 percent or more."]'::jsonb, 3, 'CIF = (C&F + any other insurance) / (1 - the sum of the CIF rates), and at 100 percent the denominator is zero. The engine refuses the call with the sentence above and forms no CIF.'),
  ('supply', 'advanced', 'module', 'm02-the-landed-cost-walk', 4, 'The course''s invented import duty of 5.75 percent prints 1399086.04 USD on BADAGRY. Which figure is it a percent of?', '["CIF, 24331931.09 USD", "C&F, 24293000.00 USD", "FOB, 23392000.00 USD", "The landed total, 26513943.86 USD"]'::jsonb, 0, 'Duty ships as percent_of_cif and bites on CIF as frozen at the end of the insurance stage. It sees none of the landed lines, which come after CIF is fixed.'),
  ('supply', 'advanced', 'module', 'm02-the-landed-cost-walk', 5, 'The invented regulatory rate of 0.0024 USD a litre prints 109854.60 USD on BADAGRY. Which quantity is it levied on?', '["The 45772.752 bill-of-lading m3", "The 45772751.75 bill-of-lading litres", "The 34000 bill-of-lading tonnes", "The cargo as one unit, whatever its size"]'::jsonb, 1, 'The regulatory line is per_litre, so it reads the litres. The per_m3 lines read the m3, the per_tonne lines the tonnes, and per_cargo is a flat charge such as the 52500.00 USD demurrage.'),
  ('supply', 'advanced', 'module', 'm02-the-landed-cost-walk', 6, 'The invented demurrage provision of 52500 is typed as per_cargo. What does that basis do to the amount?', '["The rate is multiplied by the 34000 tonnes, as the port line''s rate is.", "The rate is read as a percent of CIF.", "The rate is the charge: 52500.00 USD whatever the cargo''s size.", "The rate is spread over the 45772.752 m3 and billed per cubic metre."]'::jsonb, 2, 'A per_cargo line reads no quantity at all. It is levied once, and the walk prints it as 52500.00 USD.'),
  ('supply', 'advanced', 'module', 'm02-the-landed-cost-walk', 7, 'Insurance on BADAGRY at the invented 0.16 percent is quoted first on CIF and then on C&F, every other invented rate unchanged. Which CIF does each build print?', '["24331931.09 USD on CIF and 24331868.80 USD on C&F.", "24331931.09 USD in both builds, since the rate is unchanged.", "24331868.80 USD on CIF and 24331931.09 USD on C&F.", "24293000.00 USD in both builds, since C&F is frozen first."]'::jsonb, 0, 'The comparison table prints CIF 24331931.09 USD with insurance on CIF and 24331868.80 USD with it on C&F. 24293000.00 USD is the C&F of the walk priced with insurance on CIF.'),
  ('supply', 'advanced', 'module', 'm02-the-landed-cost-walk', 8, 'Insurance on BADAGRY moves from the invented 0.16 percent of CIF to the same rate on C&F. Why does the import duty line change as well?', '["The duty is a percent of the insurance line, so any change in the premium passes through it.", "The engine re-solves every percentage line in closed form whenever an insurance basis changes.", "The duty is a percent of C&F, and moving the premium onto C&F changes that base.", "The duty is a percent of CIF, and CIF has changed with the insurance."]'::jsonb, 3, 'The duty reads CIF, which prints 24331931.09 USD with insurance on CIF and 24331868.80 USD with it on C&F. So the duty prints 1399086.04 and 1399082.46 USD.'),
  ('supply', 'advanced', 'module', 'm02-the-landed-cost-walk', 9, 'How does landedCost reach a CIF of 24331931.09 USD when the invented insurance is quoted as a percent of CIF?', '["By iterating: guess a CIF, charge the premium on it, and repeat until the figure stops moving.", "By charging the premium on C&F, the base the template ships, and adding it to C&F once.", "It refuses, since a charge on a base that contains itself is a forward reference.", "By one division: CIF = (C&F + any other insurance) / (1 - the sum of the CIF rates)."]'::jsonb, 3, 'The engine uses the closed form. Iterating the fixed point is how the independent oracle reaches the same CIF, which is why the two figures agreeing means something.'),
  ('supply', 'advanced', 'module', 'm02-the-landed-cost-walk', 10, 'The invented duty and financing rates are left blank on BADAGRY. What does landedCost report?', '["complete false, missing Import duty and Financing and letter of credit, total 24774210.79 USD, labelled a floor.", "A refusal naming the duty, since a percent of CIF with no rate leaves the walk unable to form CIF.", "complete true, total 24774210.79 USD, with the two blank rates read as zero and listed in assumedZero.", "complete false with a total of 26513943.86 USD, the last complete build, until the two rates are typed."]'::jsonb, 0, 'The engine adds what it was given, names what it was not and labels the sum. The digest prints "A FLOOR, not a cost: 2 rate(s) not supplied." beside 24774210.79 USD.'),
  ('supply', 'advanced', 'module', 'm02-the-landed-cost-walk', 11, 'On BADAGRY the course''s invented duty is typed 0 in one build and left blank in another. Both totals print 25114857.82 USD. What tells them apart?', '["Nothing the engine prints, since a blank and a zero produce the same figure on every row of the walk.", "The duty line, which prints zero dollars in the typed build and a refusal in the blank build of the walk.", "The complete flag and the missing list: true with none missing, against false with Import duty missing.", "The total, which the blank build marks as none because the walk cannot close on a missing duty."]'::jsonb, 2, 'The totals match, so the difference sits in the flag and the list: a rate typed 0 is a rate the engine applied, and a blank is a rate it names as missing.'),
  ('supply', 'advanced', 'module', 'm02-the-landed-cost-walk', 12, 'With every invented rate left blank, landedCost prints a total of 23392000.00 USD. What is that figure?', '["The landed cost, complete true, with every blank rate read as zero.", "The FOB alone, labelled as a floor with 9 rates missing.", "The C&F value, since freight is formed from the FOB price.", "The CIF value, formed before any landed charge applies."]'::jsonb, 1, 'It is the same figure as the FOB line of the full build. The engine prints it with complete false, 9 rates missing and "A FLOOR, not a cost: 9 rate(s) not supplied."'),
  ('supply', 'advanced', 'module', 'm02-the-landed-cost-walk', 13, 'The digest prints 26513943.86 - 24774210.79 = 1739733.07 USD for BADAGRY, every rate invented. Which lines does the floor build leave out of its total?', '["The invented import duty and the invented financing line, both percents of CIF.", "The invented port and jetty lines, both levied on the bill-of-lading quantity of the cargo.", "The invented insurance and freight lines, both formed before CIF is frozen.", "The invented storage and demurrage lines, both booked at the landed stage."]'::jsonb, 0, 'The floor build is the one with the duty and financing rates blank. The full build prints them at 1399086.04 and 340647.04 USD, and the floor names both as missing.'),
  ('supply', 'advanced', 'module', 'm02-the-landed-cost-walk', 14, 'Why can the invented import duty on BADAGRY never bite on the storage bill of 121297.79 USD?', '["Storage is per m3 and a percentage line can only read a per-tonne base.", "The engine adds every percentage line last, after the per-quantity lines.", "Storage is billed to the terminal and the duty only reads the importer''s lines.", "Duty reads CIF, which is frozen before the walk reaches any landed charge."]'::jsonb, 3, 'Each base is frozen when the walk reaches it. The duty''s CIF of 24331931.09 USD is formed at the insurance stage, before any landed charge, and the financing line, also a percent of CIF, prints ahead of demurrage in the walk.'),
  ('supply', 'advanced', 'module', 'm02-the-landed-cost-walk', 15, 'A corrected density arrives for the BADAGRY cargo. Which invented landed line does the walk leave untouched?', '["Jetty throughput and discharge, levied per m3.", "Storage and handling, levied per m3.", "Port and harbour charges, levied per tonne at 103700.00 USD.", "Regulatory and inspection charges, levied per litre."]'::jsonb, 2, 'FOB and port are both formed from the 34000 tonnes, and a tonne is a mass. Jetty and storage read m3 and the regulatory line reads litres, and those volumes pass through the density.'),
  ('supply', 'advanced', 'module', 'm03-ocean-loss-and-the-litre-sold', 1, 'The course sweeps the invented ocean loss on BADAGRY from 0 to 0.45 percent, insurance on CIF. Which printed figure does not move?', '["The landed total, 26513943.86 USD", "The outturn, 45772751.75 litres", "The USD per litre sold, 0.579252", "The naira a litre sold, 880.6943"]'::jsonb, 0, 'Every charge is levied on the bill-of-lading quantity or on a value formed from it. So the landed total prints 26513943.86 USD on every row while the outturn falls to 45566774.37 litres.'),
  ('supply', 'advanced', 'module', 'm03-ocean-loss-and-the-litre-sold', 2, 'At the invented ocean loss of 0.45 percent, what outturn does the engine report for the BADAGRY cargo?', '["45681206.25 litres", "45315024.23 litres", "45566774.37 litres", "45772751.75 litres"]'::jsonb, 2, 'outturn = bill-of-lading x (1 - ocean loss / 100). 45681206.25 litres is the row at 0.2 percent, 45315024.23 the row at 1 percent and 45772751.75 the bill of lading itself.'),
  ('supply', 'advanced', 'module', 'm03-ocean-loss-and-the-litre-sold', 3, 'How does the engine form the cost of a litre sold on BADAGRY, with every rate invented for the course?', '["The landed total divided by the bill-of-lading litres, then raised by the ocean loss percent.", "The landed total with the lost litres priced as a charge, over the bill-of-lading litres.", "The FOB value divided by the outturn litres, with the landed lines added per litre after.", "The landed total divided by the outturn litres."]'::jsonb, 3, 'The importer pays the landed total and sells the outturn. At the invented 0.45 percent that is 26513943.86 USD over 45566774.37 litres, printed as 0.581870 USD a litre sold.'),
  ('supply', 'advanced', 'module', 'm03-ocean-loss-and-the-litre-sold', 4, 'The digest''s rule for the ocean loss reads "The loss divides the cost." Which reading of BADAGRY does that statement rule out?', '["Spreading the total over the litres that arrived.", "Adding the loss to the build-up as a charge in dollars.", "Holding the landed total the same on every row of the sweep.", "Charging port on the 34000 bill-of-lading tonnes."]'::jsonb, 1, 'The importer pays for the bill-of-lading quantity and sells the outturn. The loss divides the cost: the landed total stays at 26513943.86 USD and the litres it is spread over fall, so the loss is never a charge in the build-up.'),
  ('supply', 'advanced', 'module', 'm03-ocean-loss-and-the-litre-sold', 5, 'The invented ocean loss on BADAGRY is raised from 0.45 to 1 percent. Which pair of printed figures moves?', '["The outturn and the cost a litre sold: 45566774.37 to 45315024.23 litres, and 0.581870 to 0.585103 USD.", "CIF and the landed total, since the invented duty reads CIF and a lost litre carries its share of duty.", "The jetty and storage lines, since the discharge charges are levied on the volume that crosses the jetty.", "The regulatory line and the landed total, since the per-litre charge is levied on each litre received."]'::jsonb, 0, 'The loss moves only the litres the landed total is spread over. Every charge, including the per-litre regulatory line, is levied on the bill-of-lading quantity.'),
  ('supply', 'advanced', 'module', 'm03-ocean-loss-and-the-litre-sold', 6, 'Where does the ocean loss sit among the inputs to the invented BADAGRY build-up?', '["It is a landed line of IMPORT_TEMPLATE with the basis per_cargo.", "It is estimated by the engine from the voyage and the product density.", "It is an input of its own, with no row in IMPORT_TEMPLATE.", "It is folded into the invented insurance rate."]'::jsonb, 2, 'The template''s 9 lines are charges, each on a base, and none of them is the loss. The ocean loss is stated with the cargo, beside the FOB price and the exchange rate, and outturn = bill-of-lading x (1 - ocean loss / 100).'),
  ('supply', 'advanced', 'module', 'm03-ocean-loss-and-the-litre-sold', 7, 'How does the invented exchange rate of 1520.4000 naira to the dollar enter the BADAGRY landed cost?', '["On every line of the walk, so each landed charge prints in naira before the total is formed.", "On FOB alone, since the cargo is bought in dollars and every later charge is billed locally.", "On the landed total, which is converted to naira before it is divided by the outturn litres.", "Once, at the end: naira per litre sold = USD per litre sold x 1520.4000."]'::jsonb, 3, 'Every line of the walk is in dollars, and the exchange rate enters once, at the end: 0.581870 USD a litre sold becomes 884.6753 naira.'),
  ('supply', 'advanced', 'module', 'm03-ocean-loss-and-the-litre-sold', 8, 'The invented exchange rate is left out of the BADAGRY call. What does the engine report?', '["A refusal of the whole landed cost.", "The dollar cost a litre sold, with the local figure reported as none.", "The naira figure at 1520.4000, carried over as the last rate the record used.", "Both figures in dollars, the naira column copied from the dollar one."]'::jsonb, 1, 'The dollar cost a litre sold needs no exchange rate. The naira figure is the dollar figure x the exchange rate, and with no exchange rate the digest prints the local figure as none.'),
  ('supply', 'advanced', 'module', 'm03-ocean-loss-and-the-litre-sold', 9, 'Which figure does the pump price build-up of the next module start from, on the course''s invented BADAGRY record?', '["880.6943 naira a litre, the row at a loss of 0", "889.5902 naira a litre, the row at a loss of 1 percent", "884.6753 naira a litre, the row at the invented 0.45 percent loss", "882.4592 naira a litre, the row at a loss of 0.2 percent"]'::jsonb, 2, 'BADAGRY''s invented ocean loss is 0.45 percent, so its landed cost at the depot gate is 0.581870 USD a litre sold converted once, 884.6753 naira a litre.'),
  ('supply', 'advanced', 'module', 'm03-ocean-loss-and-the-litre-sold', 10, 'The walk prints FOB at 0.513357 USD per outturn litre on BADAGRY, every rate invented. Which quantity is that line spread over?', '["The outturn, 45566774.37 litres", "The bill of lading, 45772751.75 litres", "The bill of lading, 45772.752 m3", "The outturn at a loss of 1 percent, 45315024.23 litres"]'::jsonb, 0, 'The priced case carries the invented 0.45 percent loss, and its column in USD per outturn litre spreads every line over that outturn. The other options are the outturn at 1 percent and the bill of lading in two units.'),
  ('supply', 'advanced', 'module', 'm03-ocean-loss-and-the-litre-sold', 11, 'The invented jetty line prints 54927.30 USD on BADAGRY. Which two quantities does held finding H1 set side by side?', '["45772.752 m3 on the bill of lading, and the 45772.700 m3 the cargo reads when typed as a volume.", "The outturn of 45566.774 m3, which the line is levied on, and 45772.752 m3 on the bill of lading.", "45772751.75 litres on the bill of lading, and the 45772700.00 litres typed from a rounded quote.", "45772.752 m3 on the bill of lading, which the line is levied on, and the outturn of 45566.774 m3."]'::jsonb, 3, 'The engine levies the jetty and storage lines on the bill-of-lading volume. The volume discharged is the outturn, and which one a terminal bills on is a contract term.'),
  ('supply', 'advanced', 'module', 'm03-ocean-loss-and-the-litre-sold', 12, 'Why is H1 taught as a limit and never graded?', '["The engine bills the discharge lines on the outturn, and the course prints no outturn figure.", "It is held in the engines repository''s findings: the billing quantity is a contract term the engine does not know.", "The jetty and storage lines are left out of the BADAGRY landed total until the basis is settled.", "The engine refuses the jetty and storage lines until the contract basis is typed."]'::jsonb, 1, 'The digest lists H1 among the items held by the engines repository in FINDINGS-supply, taught as limits and never graded. Whether a terminal bills on the bill of lading or on the outturn is a contract term the engine does not know, and the engine answers every per-quantity line on the bill of lading.'),
  ('supply', 'advanced', 'module', 'm03-ocean-loss-and-the-litre-sold', 13, 'H1 names the jetty and storage lines. Which other invented BADAGRY lines does the same contract question reach?', '["The percentage lines: the invented duty and financing, since both are charged on CIF.", "No other line, since only a discharge charge is levied where the cargo comes ashore.", "Every per-quantity line: regulatory 109854.60 USD on 45772751.75 litres and port 103700.00 USD on 34000.0000 tonnes.", "The freight line alone, since it is the per-tonne line formed before the cargo lands."]'::jsonb, 2, 'The engine charges each line quoted per quantity on the bill-of-lading quantity. The percentage lines are charged on values, and the landed total is divided by the outturn whatever the basis.'),
  ('supply', 'advanced', 'module', 'm03-ocean-loss-and-the-litre-sold', 14, 'At an invented ocean loss of 0, what is the cost a litre sold on BADAGRY, and why?', '["0.513357 USD, because with no loss the landed lines are spread over the litres unchanged.", "0.581870 USD, because the loss is fixed in the build-up and the sweep moves only naira.", "0.585103 USD, because a loss of 0 is read as the highest row the sweep carries.", "0.579252 USD, because the outturn equals the 45772751.75 bill-of-lading litres."]'::jsonb, 3, 'With no loss the landed total of 26513943.86 USD is spread over the full bill of lading. 0.513357 USD is the FOB line alone per outturn litre at the invented 0.45 percent.'),
  ('supply', 'advanced', 'module', 'm03-ocean-loss-and-the-litre-sold', 15, 'The course sweeps the invented ocean loss on BADAGRY from 0 to 1 percent at 1520.4000 naira to the dollar. What does the naira cost a litre sold read at the two ends?', '["880.6943 naira at 0 and 889.5902 naira at 1 percent.", "884.6753 naira at both ends, since the landed total does not move.", "880.6943 naira at both ends, since the exchange rate does not move.", "889.5902 naira at 0 and 880.6943 naira at 1 percent."]'::jsonb, 0, 'The sweep prints 880.6943 naira a litre sold at a loss of 0 and 889.5902 at 1 percent. The landed total stays at 26513943.86 USD, and the outturn it is spread over falls from 45772751.75 to 45315024.23 litres.'),
  ('supply', 'advanced', 'module', 'm04-from-depot-gate-to-nozzle', 1, 'The course''s invented value added tax of 6.5 percent is the last element of the BADAGRY pump price. Which figure is it a percent of?', '["The landed cost at the depot gate, 884.6753 naira a litre", "The running total above it, 1009.2253 naira a litre", "The pump price it forms, 1074.8249 naira a litre", "The running total after the dealer, 999.6253 naira a litre"]'::jsonb, 1, 'Its basis is percent_of_running, so it adds that percent of everything above it: the landed cost, every invented margin and the invented levies.'),
  ('supply', 'advanced', 'module', 'm04-from-depot-gate-to-nozzle', 2, 'The invented value added tax of 6.5 percent is typed as a percent of the landed cost instead of the running total. What does buildPumpPrice report?', '["A pump price of 1074.8249 naira a litre, since a rate that is supplied gives the same amount on any basis.", "A pump price of 1031.3197 naira a litre, labelled a floor because the tax no longer reads the margins.", "A refusal, since percent_of_landed is a basis for the import walk and not a pump price element.", "A pump price of 1066.7292 naira a litre, complete true."]'::jsonb, 3, 'The digest prints price 1066.7292 naira a litre for that build and says it is complete true: the basis changes the amount, and every rate is still supplied.'),
  ('supply', 'advanced', 'module', 'm04-from-depot-gate-to-nozzle', 3, 'The invented depot and terminal margin is 21 naira a litre. What does it do to the running total on BADAGRY?', '["It takes it from 884.6753 to 905.6753 naira a litre.", "It adds 21 percent of 884.6753 naira a litre to the landed cost.", "It takes it from 1009.2253 to 1074.8249 naira a litre.", "It sets the terminal''s share at 0.823088."]'::jsonb, 0, 'A per_litre element adds its amount wherever it sits. The running column is the price so far, and the terminal''s share is 0.019538.'),
  ('supply', 'advanced', 'module', 'm04-from-depot-gate-to-nozzle', 4, 'Two pump elements, the invented dealer margin and the statutory levies, are blank. Which answer does the waterfall engine give?', '["complete true at 1031.3197 naira a litre, with the two blank elements taken as zero and named in assumedZero.", "REFUSED: A landed cost per litre is required, since the chain cannot be walked with two elements missing.", "complete false, both elements named as missing, price 1031.3197 naira a litre, labelled a floor.", "complete false with the price reported as none, since the tax cannot read a running total with gaps in it."]'::jsonb, 2, 'The engine keeps both missing elements visible, reports complete false and prints "A FLOOR, not a price: 2 rate(s) not supplied." beside 1031.3197 naira a litre.'),
  ('supply', 'advanced', 'module', 'm04-from-depot-gate-to-nozzle', 5, 'Against the course''s invented cap of 1040.0000 naira a litre, the complete BADAGRY price of 1074.8249 gives which answer?', '["A shortfall of -34.8249 naira a litre, and the cap covers the chain: true.", "A shortfall of 34.8249 naira a litre, and the cap covers the chain: false.", "A shortfall of -75.1751 naira a litre, and the cap covers the chain: true.", "A shortfall of 34.8249 naira a litre, and the cap covers the chain: true."]'::jsonb, 1, 'The shortfall is the chain''s price less the cap. A positive figure means the cap is below the chain''s cost, so the verdict is false.'),
  ('supply', 'advanced', 'module', 'm04-from-depot-gate-to-nozzle', 6, 'The invented cap is 1150.0000 naira a litre. What does a shortfall of -75.1751 naira a litre mean?', '["The chain loses 75.1751 naira on every litre it sells under the cap.", "The cap is below the chain''s cost by 75.1751 naira a litre.", "The government share must fall by 75.1751 naira to meet it.", "The cap sits above the chain''s price, and the cap covers the chain."]'::jsonb, 3, 'A negative shortfall means the cap sits above the price of 1074.8249 naira a litre. A positive one would mean the cap is below the chain''s cost.'),
  ('supply', 'advanced', 'module', 'm04-from-depot-gate-to-nozzle', 7, 'A reader sets the floor price of 1031.3197 naira a litre beside the invented cap of 1040.0000. Why is no cap verdict worth reading from that pair?', '["The floor build is complete false, and the complete price of 1074.8249 gives a shortfall of 34.8249 at that cap.", "The floor is always above the complete price, so a cap that clears the floor clears the full chain as well.", "The engine applies the cap to the landed cost only, so the margins left blank play no part in the verdict.", "The cap is invented and the floor is measured, so a comparison between the two carries no information."]'::jsonb, 0, 'The floor of 1031.3197 naira a litre has 2 rates missing. With every invented rate supplied the price is 1074.8249, and against 1040.0000 the shortfall is 34.8249 and the cap covers the chain: false.'),
  ('supply', 'advanced', 'module', 'm04-from-depot-gate-to-nozzle', 8, 'marginWaterfall groups the invented BADAGRY build-up by recipient. What is the Government row?', '["0.069965 naira a litre, the Government share of price", "9.6000 naira a litre, the statutory levies alone", "75.1996 naira a litre, the levies and the value added tax together", "31.2500 naira a litre, the dealer margin it regulates"]'::jsonb, 2, 'Government is the one recipient with two elements. The invented levies add 9.6000 and the invented tax is added on the running total of 1009.2253, and the grouping reports the two together with a share of 0.069965.'),
  ('supply', 'advanced', 'module', 'm04-from-depot-gate-to-nozzle', 9, 'The Government share of the BADAGRY price is 0.069965 and the invented tax rate is 6.5 percent. What separates the two figures?', '["The share is the invented tax rate restated after rounding, so the two figures describe one quantity.", "The share is the tax rate applied to the landed cost, and the rate is the tax applied to the running total.", "The rate is a fraction of the price, and the share is the rate applied to the running total above it.", "The rate applies to the tax row''s base; the share is a fraction of the final price from both government elements."]'::jsonb, 3, 'A rate belongs to a base and a share belongs to a price. 0.069965 is 75.1996 of 1074.8249 naira a litre; 6.5 percent is what the tax row applies to 1009.2253.'),
  ('supply', 'advanced', 'module', 'm04-from-depot-gate-to-nozzle', 10, 'The course removes the recipient from the invented bridging element. How does marginWaterfall treat it?', '["It assigns the element to Chain, the recipient the template gives bridging.", "It groups the 24.5000 naira a litre as Unattributed.", "It drops the element and closes the grouping on a lower price.", "It refuses the grouping until every element names a recipient."]'::jsonb, 1, 'The engine keeps the money visible and names it as unattributed, so the gap in the labelling is on the page. It does not guess the recipient.'),
  ('supply', 'advanced', 'module', 'm04-from-depot-gate-to-nozzle', 11, 'marginWaterfall is handed a build-up that the engine refused. What does it return?', '["The refusal buildPumpPrice gives: A landed cost per litre is required.", "Every share reported as none.", "The refusal landedCost gives with no FOB: An FOB price and its basis are required.", "One Unattributed row holding the price."]'::jsonb, 0, 'The digest prints marginWaterfall on a refused build-up as REFUSED: A landed cost per litre is required., the sentence buildPumpPrice gives when it has no landed cost.'),
  ('supply', 'advanced', 'module', 'm04-from-depot-gate-to-nozzle', 12, 'In the invented BADAGRY grouping, which recipient row comes first, and why?', '["Terminal at 21.0000 naira a litre, as the template''s order puts it first.", "Government at 75.1996 naira a litre, as statutory elements lead.", "Product (landed) at 884.6753 naira a litre, because the grouping runs largest first.", "Dealer at 31.2500 naira a litre, as the nozzle end is listed first."]'::jsonb, 2, 'marginWaterfall groups the build-up by recipient, largest first. The landed cost is grouped as Product (landed) with a share of 0.823088.'),
  ('supply', 'advanced', 'module', 'm04-from-depot-gate-to-nozzle', 13, 'On the invented BADAGRY waterfall, which element prints an amount that differs from its typed rate?', '["Depot and terminal margin: typed 21, added per litre to the landed cost.", "Dealer margin: typed 31.25, added per litre after the marketer.", "Bridging or equalisation: typed 24.5, added per litre after the depot.", "Value added tax: typed 6.5, a percent of the running total."]'::jsonb, 3, 'A per-litre element adds its amount, so each margin prints its typed rate: 21.0000, 31.2500 and 24.5000 naira a litre. The value added tax is typed as a percent, and the amount it adds is that percent of a base.'),
  ('supply', 'advanced', 'module', 'm04-from-depot-gate-to-nozzle', 14, 'The invented dealer margin shows a share of price of 0.029075. What is that share a fraction of?', '["The landed cost, 884.6753 naira a litre.", "The final pump price, 1074.8249 naira a litre.", "The running total above the dealer, 968.3753 naira a litre.", "The margins alone, before levies and tax."]'::jsonb, 1, 'The share column is each element''s share of the price. The dealer''s 31.2500 naira a litre prints 0.029075 against the pump price of 1074.8249 naira a litre, and the landed cost''s share is 0.823088.'),
  ('supply', 'advanced', 'module', 'm04-from-depot-gate-to-nozzle', 15, 'buildPumpPrice is called for BADAGRY with no landed cost per litre. What does it return?', '["REFUSED: A landed cost per litre is required.", "A waterfall starting from zero, labelled a floor, with the landed cost missing.", "A waterfall starting from 884.6753 naira a litre, the last landed cost it saw.", "REFUSED: Cargo quantity is required."]'::jsonb, 0, 'The waterfall starts from the landed cost per litre at the depot gate. Without it there is nothing to add the invented elements onto, and the engine refuses.'),
  ('supply', 'advanced', 'module', 'm05-what-breaks-the-price', 1, 'Against the course''s invented cap of 1150.0000 naira a litre, where does solveCrossing find the BADAGRY breakeven, with every exchange rate swept invented?', '["At 1650.0000 naira to the dollar, the first swept row whose verdict reads false.", "At 1641.7105 naira to the dollar, after 18 bisection steps.", "At 1500.0000 naira to the dollar, the last swept row whose verdict reads true.", "At 1520.4000 naira to the dollar, the invented rate the landed cost was built on."]'::jsonb, 1, 'The crossing lies between the rows at 1500.0000 and 1650.0000, and bisection finds it at 1641.7105. A sweep reports prices only at the values it was given.'),
  ('supply', 'advanced', 'module', 'm05-what-breaks-the-price', 2, 'Which bracket does priceSensitivity hand solveCrossing for the invented BADAGRY sweep?', '["1500.0000 to 1650.0000 naira to the dollar, the two rows either side of the turn.", "1300 to 1500 naira to the dollar, the range the course uses for the bracket test.", "1350.0000 to 1950.0000 naira to the dollar, the swept rows inside the two ends.", "1200.0000 to 2100.0000 naira to the dollar, the lowest to the highest value swept."]'::jsonb, 3, 'The bracket the engine halves is the whole swept range. The rows at 1500.0000 and 1650.0000 show where the crossing lies; they are not the bracket.'),
  ('supply', 'advanced', 'module', 'm05-what-breaks-the-price', 3, 'solveCrossing is run against the invented cap over a bracket from 1300 to 1500 naira to the dollar. What does it return?', '["found false; REFUSED: No crossing in the range searched. The outcome has the same sign at both ends.", "found true at 1500, the end of the bracket nearer the crossing, after 18 bisection steps.", "REFUSED: The search bracket is not a valid interval, since the crossing lies above it.", "found true at 1641.7105, since the engine widens the bracket until the sign changes."]'::jsonb, 0, 'Both end shortfalls, -211.7551 and -87.8167 naira a litre, are negative. The engine does not search outside the bracket it was handed and returns no value.'),
  ('supply', 'advanced', 'module', 'm05-what-breaks-the-price', 4, 'solveCrossing is handed the invented exchange rate bracket written backwards, 2100 to 1200. Which answer does it give?', '["It swaps the ends and finds 1641.7105.", "REFUSED: No crossing in the range searched. The outcome has the same sign at both ends.", "REFUSED: The search bracket is not a valid interval.", "It halves from the high end and reports none."]'::jsonb, 2, 'The digest prints the bracket written backwards, 2100 to 1200, as that refusal, with no breakeven. The same-sign refusal belongs to a valid bracket that holds no crossing, such as 1300 to 1500.'),
  ('supply', 'advanced', 'module', 'm05-what-breaks-the-price', 5, 'The breakeven search is run on the invented BADAGRY chain with no cap. What does the engine report?', '["breakeven 1500.0000", "breakeven 1641.7105", "breakeven none", "breakeven 2100.0000"]'::jsonb, 2, 'With no cap there is nothing to cross. The engine does not invent a cap to search against, and a breakeven of none is a different answer from a figure of zero.'),
  ('supply', 'advanced', 'module', 'm05-what-breaks-the-price', 6, 'The search over the invented rates 1300 to 1500 prints end shortfalls of -211.7551 and -87.8167 naira a litre. Where does each come from?', '["Both are sweep rows, at 1300 and at 1500, printed again beside the refusal for comparison.", "The -87.8167 matches the sweep row at 1500.0000; 1300 has no sweep row, so the -211.7551 is printed only here.", "The -211.7551 is the sweep row at 1200.0000; the -87.8167 is the midpoint of the bracket.", "Both are the search''s own evaluations, since no sweep row falls inside the 1300 to 1500 bracket."]'::jsonb, 1, 'The sweep holds a row at 1500.0000 with a shortfall of -87.8167 and a verdict of true. The swept values run 1200.0000, 1350.0000, 1500.0000 and on, so 1300 has no row, and its shortfall appears only beside the refusal.'),
  ('supply', 'advanced', 'module', 'm05-what-breaks-the-price', 7, 'Why does solveCrossing return no value for the invented 1300 to 1500 bracket?', '["At 1500 the shortfall is positive, so the crossing lies below the bracket and out of reach.", "Values are returned only for brackets that start at the lowest swept rate.", "A bracket must span 18 bisection steps to report a crossing.", "Both ends read a negative shortfall, so the price does not meet the cap inside the bracket."]'::jsonb, 3, 'If the price does not cross the cap inside the range searched, the engine says so and returns no value. A negative shortfall means the cap sits above the price, and it does at 1300 and at 1500.'),
  ('supply', 'advanced', 'module', 'm05-what-breaks-the-price', 8, 'Moving the invented exchange rate from 1200.0000 to 2100.0000, which printed figure moves with it besides the landed cost?', '["The Government figure, which reads 97.1210 naira a litre at 2100.0000.", "The invented levies, which are charged as a share of the landed cost at the gate.", "The invented dealer margin, which is quoted per dollar of cargo.", "No other figure; margins and levies are per litre."]'::jsonb, 0, 'The per-litre margins and levies add their amounts on every row. The tax is a percent of the running total, which holds the landed cost, so the Government figure moves from 74.4281 at 1500.0000 to 97.1210 naira a litre at 2100.0000.'),
  ('supply', 'advanced', 'module', 'm05-what-breaks-the-price', 9, 'What does priceSensitivity do at each invented exchange rate it sweeps on BADAGRY?', '["It re-prices the whole chain at that rate.", "It scales the base price of 1074.8249 by the rate.", "It moves the landed cost and holds every other amount.", "It solves for the cap at that rate."]'::jsonb, 0, 'priceSensitivity re-prices the whole chain at each value of one driver. The element table shows the landed cost and the Government figure both moving, 872.8052 and 74.4281 naira a litre at 1500.0000 against 1221.9272 and 97.1210 at 2100.0000, and the cap stays at 1150.0000.'),
  ('supply', 'advanced', 'module', 'm05-what-breaks-the-price', 10, 'Which pump price and verdict does the invented sweep print at 1500.0000 naira to the dollar, against the cap of 1150.0000?', '["At 1074.8249 naira a litre, as at the base rate, the cap covers it.", "At 1155.1370, the cap does not cover it.", "At 1062.1833 naira a litre, the cap does not cover it.", "At 1062.1833 naira a litre, the cap covers it."]'::jsonb, 3, 'The row at 1500.0000 prints 1062.1833 naira a litre, a shortfall of -87.8167 and a verdict of true. 1074.8249 is the price at the invented base rate of 1520.4000, and 1155.1370 the row at 1650.0000.'),
  ('supply', 'advanced', 'module', 'm05-what-breaks-the-price', 11, 'In the invented sweep, what are the shortfalls at 1650.0000 and at 2100.0000 naira to the dollar?', '["-87.8167 and 191.0445 naira a litre", "5.1370 and 283.9982 naira a litre", "98.0908 and 1433.9982 naira a litre", "-75.1751 and 283.9982 naira a litre"]'::jsonb, 1, 'The shortfall is the price less the invented cap. 1155.1370 at 1650.0000 and 1433.9982 at 2100.0000 sit above the cap by those figures, and both verdicts read false.'),
  ('supply', 'advanced', 'module', 'm05-what-breaks-the-price', 12, 'What landed cost a litre does the chain carry at an invented 1650.0000 naira to the dollar?', '["872.8052 naira a litre", "884.6753 naira a litre", "960.0857 naira a litre", "1221.9272 naira a litre"]'::jsonb, 2, 'The element table prints 960.0857 at 1650.0000. 872.8052 is the row at 1500.0000, 1221.9272 the row at 2100.0000, and 884.6753 the landed cost at the invented base rate of 1520.4000.'),
  ('supply', 'advanced', 'module', 'm05-what-breaks-the-price', 13, 'What does the invented exchange rate sensitivity table say about the ocean loss and the exchange rate moving together?', '["That the two effects add, so the ocean loss sweep can be stacked on each row.", "That the exchange rate dominates, since it multiplies every dollar in the chain.", "That the breakeven falls by the loss percent.", "Nothing; it moves one input and holds every other at its BADAGRY value."]'::jsonb, 3, 'Each sweep is a separate single-driver table. Neither says what happens when two inputs move at once, and neither assigns a likelihood to any row.'),
  ('supply', 'advanced', 'module', 'm05-what-breaks-the-price', 14, 'solveCrossing is handed the invented BADAGRY chain and the cap. Which value does it search for?', '["The exchange rate at which the pump price meets the cap.", "The cap at which the pump price meets the base exchange rate.", "The pump price at the invented base rate of 1520.4000.", "The landed cost at which the Government figure meets the cap."]'::jsonb, 0, 'priceSensitivity re-prices the chain at each value of one driver, here the exchange rate, and solveCrossing bisects for the value at which the price meets the cap. On BADAGRY it finds 1641.7105 naira to the dollar against 1150.0000.'),
  ('supply', 'advanced', 'module', 'm05-what-breaks-the-price', 15, 'What does the invented sensitivity table leave out, which a reader might be tempted to take from it?', '["The shortfall at each rate, which it reports only for the rows that fail.", "The verdict at each rate, which it leaves to be read from the breakeven.", "Any likelihood for a row, such as how probable a move to 1800.0000 is.", "The pump price at each rate, since it carries only the landed cost."]'::jsonb, 2, 'The table is a set of re-pricings at stated values, read row by row. A probability over the exchange rate, or a valuation of the chain, is outside this course.'),
  ('supply', 'advanced', 'module', 'm06-the-expert-reading', 1, 'Held finding H2 is stated as counts on the two templates. Which counts are they?', '["IMPORT_TEMPLATE ships 7 of 9 rates as none, keeping the freight and insurance rates, and PUMP_TEMPLATE 7 of 7.", "IMPORT_TEMPLATE ships 9 of 9 rates as none, and PUMP_TEMPLATE ships its value added tax rate alone of 7.", "IMPORT_TEMPLATE ships 9 of 9 rates as none, and PUMP_TEMPLATE 7 of 7.", "IMPORT_TEMPLATE ships its demurrage figure alone and every other rate as none, and PUMP_TEMPLATE 7 of 7."]'::jsonb, 2, 'H2: the volume correction coefficient tables and every published rate stay unshipped. That is why every rate in this tier is invented for the course and says so.'),
  ('supply', 'advanced', 'module', 'm06-the-expert-reading', 2, 'H1 is a held finding on the invented BADAGRY walk. What is it?', '["The discharge charges are billed on the bill-of-lading quantity, and which quantity a terminal bills on is a contract term the engine does not know.", "The discharge charges are billed on the outturn, and the engine cannot say what the bill of lading held once the ocean loss is typed in.", "The invented jetty and storage rates are unverified, and the engine refuses both lines until a published rate is confirmed against them.", "The ocean loss is an input, and the engine cannot estimate it from the voyage, so every outturn in the course is held back from grading."]'::jsonb, 0, 'On BADAGRY the jetty and storage lines, 54927.30 and 121297.79 USD, rest on the 45772.752 m3 invoiced while 45566.774 m3 came ashore. H1 records that the engine cannot choose between them.'),
  ('supply', 'advanced', 'module', 'm06-the-expert-reading', 3, 'For insurance quoted on CIF, how do the engine and its independent oracle each reach CIF?', '["The engine iterates the fixed point; the oracle uses the closed form.", "Both iterate the fixed point, from a first guess of C&F.", "Both use the closed form, the oracle in rational arithmetic.", "The engine uses a closed form; the oracle iterates the fixed point."]'::jsonb, 3, 'The fuelpricing oracle''s method column lists insurance on CIF by fixed-point iteration, where the engine uses a closed form. A golden figure beside an engine figure is two methods agreeing.'),
  ('supply', 'advanced', 'module', 'm06-the-expert-reading', 4, 'For the invented BADAGRY exchange rate breakeven, which way does the pairing between engine and oracle run?', '["The engine solves in closed form; the oracle bisects inside the swept bracket.", "The engine bisects; the oracle solves the breakeven in closed form.", "Both bisect, the oracle with a tighter tolerance on the sign change.", "The engine bisects; the oracle re-runs the sweep at finer steps."]'::jsonb, 1, 'The pair runs the opposite way to the insurance pair, where the engine is the closed form. The fuelpricing oracle''s method column lists a closed-form FX breakeven.'),
  ('supply', 'advanced', 'module', 'm06-the-expert-reading', 5, 'What do the oracles never check in this course?', '["The verdicts, such as whether a cap covers the chain.", "The wording of a refusal.", "The engine''s figures on the landed cost walk.", "The Erlang C by the exact factorial form."]'::jsonb, 1, 'The oracles check figures and verdicts. Every refusal sentence the course quotes is the engine''s own and is quoted rather than checked, which is why it is quoted verbatim.'),
  ('supply', 'advanced', 'module', 'm06-the-expert-reading', 6, 'The published source column reads none on both golden file rows. What does that tell a reader about the course''s figures?', '["Every figure is unvalidated, since an oracle without a published source can only restate the engine''s own figures in its own words.", "Every rate has been checked against the regulation in force, and the column records that no other published source was needed.", "The oracles and the engine share one source file, so a golden figure is the engine''s figure saved at the time of the last release.", "No rate or coefficient is a published figure, and each golden figure is an independent method agreeing with the engine."]'::jsonb, 3, 'The terminal row reads none because no coefficient table is shipped, and the pricing row because every rate is synthetic. Each golden file is written by an independent stdlib Python oracle, and the volume correction form is pinned by tests.'),
  ('supply', 'advanced', 'module', 'm06-the-expert-reading', 7, 'No coefficient table is shipped, so how is the volume correction form pinned?', '["By tests asserting the form and two invariants: a VCF of exactly 1 at 15 C and below 1 above it.", "By comparing the synthetic row against a published commodity group row to six decimals at each temperature swept.", "By the terminal oracle, rebuilding the VCF from tank geometry.", "By the typed AKODO VCFs, read as the reference."]'::jsonb, 0, 'The invariants need no coefficient. On the course''s synthetic row, the VCF at 15 C is 1.000000, exactly one: true.'),
  ('supply', 'advanced', 'module', 'm06-the-expert-reading', 8, 'What does the terminal golden file, terminaldepot_cases.json, carry?', '["3 landed cost cases, 1 truck lane, 1 fleet and 1 station.", "4 dips, 3 refusals, 4 queues, 4 reconciled days and 1 station.", "4 dips, 4 refusals, 4 queues, 3 reconciled days and 1 tank farm.", "1 pump build-up with its breakeven, and 4 queues."]'::jsonb, 2, 'The landed cost cases (floor, full and insurance on CIF), the lane, the fleet, the pump build-up and the station are carried by fuelpricing_cases.json.'),
  ('supply', 'advanced', 'module', 'm06-the-expert-reading', 9, 'Among the rules the engines keep, IB-T1 and IB-T2 together hold 5453.100 m3 over a combined heel of 420.000 m3, and their pumpable stock prints as 5078.400 m3. Which rule gives that figure?', '["The pair''s stock less the pair''s heel, taken as one pool.", "Pumpable stock is counted tank by tank, each tank''s stock above its own heel.", "Pumpable stock is corrected to standard volume, while the stock is gross observed.", "A reserve above the heel is held back on every tank before it counts as pumpable."]'::jsonb, 1, 'The rule reads: pumpable stock is counted tank by tank, and the digest measures it on IB-T1 and IB-T2 as 5078.400 m3 of pumpable stock. Each tank''s pumpable stock is its stock above its own heel and never below zero, and no pump lends one tank''s volume to another''s heel.'),
  ('supply', 'advanced', 'module', 'm06-the-expert-reading', 10, 'Among the rules the engines keep, which one does the sentence "Arrival rate and load time are both needed." enforce?', '["Bays are a whole number, one or more.", "throughputEconomics needs the throughput and the fee.", "A load time of zero minutes is refused.", "A day is not closed without its opening stock."]'::jsonb, 2, 'The digest lists the rule "a load time of zero minutes is refused" with that sentence. The bays rule prints "The number of bays must be a whole number, one or more.", the money rule "Throughput and the throughput fee are both needed for the money answer." and the opening stock rule "No opening stock, so the day cannot be closed."'),
  ('supply', 'advanced', 'module', 'm06-the-expert-reading', 11, 'throughputEconomics takes a blank cost as zero and names it in assumedZero. How does landedCost treat a blank rate?', '["It takes the rate as zero and names it in assumedZero, as the depot ledger does.", "It refuses the whole walk until every one of the 9 rates is typed.", "It fills the rate from the template, which ships each rate as none.", "It leaves the line out, names it as missing and labels the total a floor."]'::jsonb, 3, 'Both engines name what they did not get. The depot ledger reports its margin with assumedZero; the walk reports complete false and a total the engine calls a floor.'),
  ('supply', 'advanced', 'module', 'm06-the-expert-reading', 12, 'The AKODO demonstration takes an opening stock from the day''s own closing dip. Why is that rule in the list the engines keep?', '["It balances every day and so measures nothing, which is why the opening stock is an input.", "It closes the day at the dipped standard volume, the one figure the reconciliation is built to check.", "It is the method the engine uses when the opening stock is left blank on a reconciliation.", "It shows the tolerance is set too wide, since every row sits within it with nothing unaccounted."]'::jsonb, 0, 'An opening stock derived from the day''s own closing dip balances every day and measures nothing: every row of the demonstration balances, so none of them measured anything. A day is not closed without its opening stock.'),
  ('supply', 'advanced', 'module', 'm06-the-expert-reading', 13, 'Which two things does the engines repository keep unshipped under held finding H2?', '["The strapping tables of the AKODO tanks and the dips read against them.", "The diesel emission factor and the typical product densities.", "The golden files and the independent oracles that write them.", "The volume correction coefficient tables and every published rate."]'::jsonb, 3, 'H2: the volume correction coefficient tables and every published rate stay unshipped. PRODUCT_REFERENCE ships typical densities, and the two golden files and their oracles are listed in the oracle table.'),
  ('supply', 'advanced', 'module', 'm06-the-expert-reading', 14, 'Among the rules the engines keep, what does throughputEconomics report for a loss when no product density is supplied?', '["No loss weight and no emissions, with a carbon note that says why.", "The loss weighed at the typical density PRODUCT_REFERENCE lists.", "A refusal of the whole money answer until the density is typed.", "Emissions of zero kg CO2e, with the loss weight reported as none."]'::jsonb, 0, 'The rule reads: a loss with no density has no weight and no emissions, and the carbon note says why. The money answer needs only the throughput and the fee, and PRODUCT_REFERENCE is read only when a caller passes a density in.'),
  ('supply', 'advanced', 'module', 'm06-the-expert-reading', 15, 'Reading the invented BADAGRY chain end to end, where do the ocean loss and the exchange rate each enter?', '["The loss is added to the landed total as a charge; the exchange rate converts each landed line to naira.", "The loss reduces the per-quantity charges to the outturn; the exchange rate converts the FOB value first.", "The loss divides the landed total over the outturn; the exchange rate converts the dollar cost a litre sold once.", "Both enter at the pump, where the loss is a margin and the rate is applied to the running total."]'::jsonb, 2, 'The landed total of 26513943.86 USD is spread over 45566774.37 litres, 0.581870 USD a litre sold, then converted once at the invented 1520.4000 to 884.6753 naira a litre.'),
  ('supply', 'advanced', 'final', null, 1, 'A wrong density certificate is typed for BADAGRY, whose FOB price of 688.00 USD a tonne is invented. Which printed line of the walk is safe from the mistake?', '["The regulatory line, 109854.60 USD, since the per-litre charge is fixed in the template.", "The storage line, 121297.79 USD, since storage is billed on the tank the cargo fills.", "The jetty line, 54927.30 USD, since the jetty is paid per call and never per volume.", "The FOB cargo value, 23392000.00 USD, since it is a price per tonne on 34000 tonnes."]'::jsonb, 3, 'FOB is 688.00 USD a tonne times 34000 tonnes, and no density enters it. The volume lines would all be re-formed from the corrected certificate.'),
  ('supply', 'advanced', 'final', null, 2, 'cargoQuantities returns 45772751.75 litres for BADAGRY. What role does that litre figure play later in the tier?', '["It is the bill-of-lading quantity the per-litre line is levied on and the invented ocean loss is taken from.", "It is the outturn, the litres the importer sells after the invented ocean loss has been taken off the cargo.", "It is the quantity the landed total is divided by to give the cost of each litre that reaches the pump.", "It is the rounded figure typed from a quote, which is why it returns 33999.9616 tonnes when entered."]'::jsonb, 0, 'The landed total is spread over what arrives, 45566774.37 litres at the invented 0.45 percent loss. The litres returned by cargoQuantities are what was loaded and paid for.'),
  ('supply', 'advanced', 'final', null, 3, 'Ocean freight typed as a percent of C&F is refused on the invented BADAGRY walk. Which other entry does the digest show refused with the same sentence?', '["A charge with the stage \"customs\".", "Insurance on CIF at 100 percent.", "Import duty typed as a percent of CIF.", "Ocean freight typed as a percent of CIF."]'::jsonb, 3, 'Freight on C&F and freight on CIF both read "Ocean freight is a percentage of a value that is not formed until after freight." A customs stage and CIF insurance at 100 percent have sentences of their own, and duty on CIF is the rate BADAGRY prices at 5.75 percent.'),
  ('supply', 'advanced', 'final', null, 4, 'With the invented marine insurance quoted on C&F in place of CIF, what landed total does BADAGRY print?', '["26513943.86 USD", "25114857.82 USD", "24774210.79 USD", "26513877.12 USD"]'::jsonb, 3, 'Moving the premium onto C&F lowers it to 38868.80 USD, which lowers CIF and so the duty that reads CIF. The build with the invented premium on CIF closes at 26513943.86 USD.'),
  ('supply', 'advanced', 'final', null, 5, 'The engine labels an incomplete build-up a floor. On the invented BADAGRY pump price, which figure carries that label?', '["1066.7292 naira a litre, with the tax typed on the landed cost.", "1031.3197 naira a litre, with the dealer margin and levies blank.", "24774210.79 USD, with the duty and financing blank.", "1074.8249 naira a litre, with every invented element supplied."]'::jsonb, 1, 'The pump sentence is "A FLOOR, not a price: 2 rate(s) not supplied." The walk''s floor of 24774210.79 is in US dollars for the cargo, and 1066.7292 is complete true.'),
  ('supply', 'advanced', 'final', null, 6, 'Every invented rate in the BADAGRY import template is supplied. How does landedCost label the build-up?', '["complete true, labelled a floor until a cap is set.", "complete true; All supplied rates applied.", "complete false, since the ocean loss has no row in the template.", "complete true, with the ocean loss named in assumedZero."]'::jsonb, 1, 'The full walk prints landed total 26513943.86 USD, complete true and "All supplied rates applied." The ocean loss is stated with the cargo and is not a template rate, and a floor is the label for a build-up with rates missing.'),
  ('supply', 'advanced', 'final', null, 7, 'The invented exchange rate moves while the BADAGRY cargo and every invented import rate stay the same. Which figure is unchanged?', '["The landed total in dollars, 26513943.86 USD.", "The landed cost at the depot gate in naira a litre.", "The Government row of the pump price in naira.", "The shortfall against the invented cap of 1150.0000."]'::jsonb, 0, 'Every line of the walk is in dollars, and the exchange rate enters once, at the end. So the naira landed cost, the tax built on it and the shortfall all move with the rate.'),
  ('supply', 'advanced', 'final', null, 8, 'Across the invented exchange rate sweep the Government figure moves with the rate, reaching 97.1210 naira a litre at 2100.0000. Why does the dealer margin stay at its invented 31.2500?', '["The dealer margin is quoted in naira while the levies are quoted in dollars, so only the levies move with the rate.", "The dealer margin is per litre, while the tax in the Government row reads a running total that holds the landed cost.", "The dealer is paid after the tax, so the running total the dealer reads is fixed before the landed cost is added.", "The dealer margin is a share of the price, and a share of the price is held fixed when the price is re-priced."]'::jsonb, 1, 'A per-litre element adds its amount, and a percent of the running total adds that percent of everything above it. The invented levies are per litre too; the tax element is what moves the Government row, since its base contains the landed cost.'),
  ('supply', 'advanced', 'final', null, 9, 'How many bisection steps does the engine report for the invented BADAGRY breakeven?', '["9", "24", "18", "12"]'::jsonb, 2, 'breakeven: found true, at 1641.7105 naira to the dollar, after 18 bisection steps.'),
  ('supply', 'advanced', 'final', null, 10, 'Which landed cost cases does fuelpricing_cases.json carry?', '["2: full and floor, with insurance on C&F.", "4: one for each insurance and duty basis.", "1: the full BADAGRY build-up alone.", "3: floor, full and insurance on CIF."]'::jsonb, 3, 'The pricing golden file carries 3 landed cost cases (floor, full, insuranceOnCif), 1 truck lane, 1 fleet, 1 pump build-up with its breakeven exchange rate, and 1 station.'),
  ('supply', 'advanced', 'final', null, 11, 'What does the fuelPricing constant LITRES_PER_M3 hold, and where is it used?', '["742.8, to turn tonnes into m3 at the BADAGRY density.", "0.158987294928, to turn m3 into barrels of cargo.", "745, to turn tonnes into m3 when no density is typed.", "1000, to turn the cargo''s m3 into litres."]'::jsonb, 3, 'litres = m3 x 1000. 0.158987294928 is M3_PER_BBL, and 742.8 and 745 are densities, one typed and one from PRODUCT_REFERENCE.'),
  ('supply', 'advanced', 'final', null, 12, 'Why does the course run the same 34000 tonnes through every density in PRODUCT_REFERENCE, 35416.667 m3 at 960 kg/m3 among them?', '["To show which product the BADAGRY cargo is, since the volume identifies the product.", "To give the default the engine applies when the density is left out of a call, as the PMS row does.", "To show what a wrong density moves in the volume, which is why the certificate figure is typed.", "To show that the barrel figure is independent of the density typed."]'::jsonb, 2, 'Nothing in the module reads those densities unless a caller passes one in. The same tonnes read 45637.584 m3 at 745 and 35416.667 m3 at 960 kg/m3.'),
  ('supply', 'advanced', 'final', null, 13, 'Quoted on CIF, the course''s invented 0.16 percent premium comes to which dollar amount on BADAGRY?', '["38868.80 USD", "52500.00 USD", "38931.09 USD", "54927.30 USD"]'::jsonb, 2, 'On CIF the premium is part of the value it is charged on and prints 38931.09 USD. 38868.80 USD is the same invented rate on C&F.'),
  ('supply', 'advanced', 'final', null, 14, 'The invented port and harbour rate is 3.05. Which quantity does it read to print 103700.00 USD?', '["34000 tonnes", "45772.752 m3", "45772751.75 litres", "287901.9470 barrels"]'::jsonb, 0, '103700.00 USD over 34000 tonnes is the invented 3.05 a tonne. A density would reach this line only if it were quoted by volume.'),
  ('supply', 'advanced', 'final', null, 15, 'The invented financing and letter of credit rate of 1.4 prints 340647.04 USD. On which basis is it charged?', '["percent_of_fob", "percent_of_cf", "per_m3", "percent_of_cif"]'::jsonb, 3, 'Financing is quoted on CIF, the value frozen at the end of the insurance stage, 24331931.09 USD. It sees no landed line.'),
  ('supply', 'advanced', 'final', null, 16, 'Which naira figure a litre sold goes with the 0.2 percent row of the invented ocean loss sweep?', '["880.6943", "884.6753", "889.5902", "882.4592"]'::jsonb, 3, 'The rows run 880.6943 at 0, 882.4592 at 0.2, 884.6753 at 0.45 and 889.5902 at 1 percent, each at the invented 1520.4000 naira to the dollar.'),
  ('supply', 'advanced', 'final', null, 17, 'Why do the invented duty and financing lines sit outside the contract question H1 raises?', '["They are charged before the cargo is discharged, and H1 covers only what happens once the cargo is ashore.", "They are charged on a value, CIF, and H1 is a question about which quantity a per-quantity line is billed on.", "They are paid to the government, and H1 covers only what the importer pays to the terminal it discharges into.", "They are refused when the outturn is typed, so the engine never has to pick between the two quantities for them."]'::jsonb, 1, 'H1 asks which quantity a line quoted per tonne, per m3 or per litre is billed on. Duty at the invented 5.75 percent and financing at the invented 1.4 percent read CIF, 24331931.09 USD, and hold no quantity to choose.'),
  ('supply', 'advanced', 'final', null, 18, 'What is the running total on the invented BADAGRY waterfall once the statutory levies are added?', '["999.6253 naira a litre", "1074.8249 naira a litre", "1009.2253 naira a litre", "968.3753 naira a litre"]'::jsonb, 2, 'The invented levies of 9.6 add 9.6000 to 999.6253. The tax then reads 1009.2253 and the price is 1074.8249.'),
  ('supply', 'advanced', 'final', null, 19, 'What share of the invented BADAGRY price is the landed cost at the depot gate?', '["0.069965", "0.061033", "0.029075", "0.823088"]'::jsonb, 3, '884.6753 naira a litre is grouped as Product (landed) with a share of 0.823088. 0.069965 is Government, 0.061033 the tax row and 0.029075 the dealer.'),
  ('supply', 'advanced', 'final', null, 20, 'Which recipient does the invented transport to station element of 19.8 naira a litre pay?', '["Chain", "Marketer", "Transporter", "Terminal"]'::jsonb, 2, 'PUMP_TEMPLATE gives transport the recipient Transporter. Chain receives the bridging element, Marketer the marketer margin and Terminal the depot margin.'),
  ('supply', 'advanced', 'final', null, 21, 'On the invented sweep against the cap of 1150.0000, on which rows does the verdict read true?', '["The four rows from 1650.0000 to 2100.0000 naira to the dollar.", "Every row, since the price at the invented base rate is below the cap.", "No row, since the cap is below the price at every swept exchange rate.", "The three rows from 1200.0000 to 1500.0000 naira to the dollar."]'::jsonb, 3, 'The shortfall is negative at 1200.0000, 1350.0000 and 1500.0000 and positive from 1650.0000, where it is 5.1370 naira a litre.'),
  ('supply', 'advanced', 'final', null, 22, 'The engine''s CIF of 24331931.09 USD on BADAGRY, with the invented insurance on CIF, is checked how?', '["An oracle reads it off a published marine insurance table and compares the two to the cent.", "An oracle reaches it by iterating the fixed point, a different road from the engine''s closed form.", "The engine solves it twice, once on C&F and once on CIF, and checks that the two agree.", "It is not checked, since insurance on CIF is circular and no second method can reach it."]'::jsonb, 1, 'Insurance on CIF by fixed-point iteration is in the fuelpricing oracle''s method column. The published source column for that file reads none: every rate is synthetic.'),
  ('supply', 'advanced', 'final', null, 23, 'RATE_DISCLAIMER and held finding H2 describe one decision. What is it?', '["The engine ships one market''s regulated rates and asks the user to confirm them before use.", "The engine ships no rate, so every rate is a required input and each one in this course is invented.", "The engine ships typical rates as a starting point, as PRODUCT_REFERENCE does for densities.", "The engine ships rates for the import walk and leaves the pump elements for the user to type."]'::jsonb, 1, 'RATE_DISCLAIMER says every rate is a required input, since duties, levies and regulated margins are set by regulation, differ by market and change. H2: every template rate is absent, 9 of 9 on IMPORT_TEMPLATE and 7 of 7 on PUMP_TEMPLATE, and every rate in this course is invented.'),
  ('supply', 'advanced', 'final', null, 24, 'What C&F does landedCost print for the invented BADAGRY cargo?', '["24293000.00 USD", "23392000.00 USD", "24331931.09 USD", "26513943.86 USD"]'::jsonb, 0, 'The walk runs FOB, then freight (C&F): 23392000.00 USD of cargo and 901000.00 USD of the invented freight. 24331931.09 USD is CIF, formed after insurance, and 26513943.86 USD the landed total.'),
  ('supply', 'advanced', 'final', null, 25, 'The BADAGRY cost a litre sold prints to six decimals in dollars and to four in naira. Which pair is it at the invented 0.45 percent loss?', '["0.579252 USD and 880.6943 naira", "0.581870 USD and 884.6753 naira", "0.585103 USD and 889.5902 naira", "0.513357 USD and 884.6753 naira"]'::jsonb, 1, '0.581870 USD a litre sold x the invented 1520.4000 is 884.6753 naira. 0.513357 USD is the FOB line alone per outturn litre.'),
  ('supply', 'advanced', 'final', null, 26, 'What share of the invented BADAGRY pump price does the value added tax row carry?', '["0.069965", "0.019538", "0.061033", "0.008932"]'::jsonb, 2, 'The share column divides the row''s amount by 1074.8249 naira a litre. 0.069965 is the Government row, levies and tax together, and 0.008932 the levies row.'),
  ('supply', 'advanced', 'final', null, 27, 'Over the course''s 1300 to 1500 bracket, what do the two negative end shortfalls say about the invented cap?', '["It fails the chain at both ends, so the crossing must lie below 1300 and the bracket must move down.", "It covers the chain at one end and fails it at the other end.", "It sits exactly on the price at 1500, which is the breakeven.", "It covers the chain at both ends, so the price does not meet it anywhere searched."]'::jsonb, 3, 'A negative shortfall means the cap sits above the price. -211.7551 and -87.8167 have the same sign, so there is nothing to halve towards.'),
  ('supply', 'advanced', 'final', null, 28, 'Which pair of elements makes up the Government recipient on the invented BADAGRY waterfall?', '["Statutory levies at the pump and Value added tax.", "Value added tax alone.", "Statutory levies at the pump alone.", "Statutory levies at the pump, Value added tax and Bridging or equalisation."]'::jsonb, 0, 'The Government row reads 75.1996 naira a litre with the elements Statutory levies at the pump and Value added tax. Bridging or equalisation is paid to Chain, and removing its recipient sends it to Unattributed.'),
  ('supply', 'advanced', 'final', null, 29, 'cargoQuantities refuses the unit "kg" and landedCost refuses the stage "customs". What do the two refusals share?', '["Both are forward references to a value the walk has not formed, so both carry the same sentence.", "Each names a label the engine does not know and refuses the call.", "Both are density errors, since kilograms and customs charges are each formed from a volume.", "Both are read as zero and named, so the answer is labelled a floor until the label is fixed."]'::jsonb, 1, 'The digest prints REFUSED: Unknown quantity unit "kg". for cargoQuantities and REFUSED: Customs processing has an unknown stage "customs". for landedCost. Neither returns a figure, and neither is a forward reference or a floor.'),
  ('supply', 'advanced', 'final', null, 30, 'Which invented BADAGRY figure changes when the ocean loss changes: the landed total, the bill-of-lading litres, the regulatory line or the outturn?', '["The outturn", "The landed total", "The bill-of-lading litres", "The regulatory line"]'::jsonb, 0, 'The landed total reads 26513943.86 USD on every row of the sweep and the bill of lading 45772751.75 litres, and the regulatory line, 109854.60 USD, is charged on those bill-of-lading litres. The outturn is the one figure of the four that falls as the loss rises.'),
  ('supply', 'advanced', 'final', null, 31, 'What is the running total after the invented marketer margin of 18.4 naira a litre?', '["968.3753 naira a litre", "949.9753 naira a litre", "999.6253 naira a litre", "930.1753 naira a litre"]'::jsonb, 0, 'The marketer margin takes the running total from 949.9753 to 968.3753. 999.6253 is after the dealer and 930.1753 after bridging.'),
  ('supply', 'advanced', 'final', null, 32, 'What shortfall does the invented sweep print at 1950.0000 naira to the dollar?', '["98.0908 naira a litre", "283.9982 naira a litre", "191.0445 naira a litre", "1341.0445 naira a litre"]'::jsonb, 2, 'The price at 1950.0000 is 1341.0445 naira a litre, which is 191.0445 above the invented cap. 98.0908 is the row at 1800.0000 and 283.9982 the row at 2100.0000.'),
  ('supply', 'advanced', 'final', null, 33, 'percent_of_running appears in which of the module''s basis lists, and on which invented BADAGRY line?', '["CHARGE_BASIS alone, on the import duty.", "PRICE_ELEMENT_BASIS alone, on the value added tax.", "Both lists, on the duty and the tax, since each is a percentage line.", "PRICE_ELEMENT_BASIS alone, on the levies."]'::jsonb, 1, 'The pump template''s one percentage line is the tax, on percent_of_running. The levies are per_litre, and the duty is a CHARGE_BASIS line on percent_of_cif.'),
  ('supply', 'advanced', 'final', null, 34, '884.6753 naira a litre appears in two modules on the invented BADAGRY record. Which two roles does it play?', '["The pump price before tax, and the base the invented value added tax reads.", "The naira cost a litre sold, and the landed cost the pump waterfall starts from.", "The landed total per bill-of-lading litre, and the cap the waterfall is checked on.", "The naira cost a litre at zero loss, and the landed cost at the swept 1500.0000."]'::jsonb, 1, 'The walk ends at 0.581870 USD a litre sold, converted once to 884.6753 naira. buildPumpPrice starts from that figure, whose share of the price is 0.823088.'),
  ('supply', 'advanced', 'final', null, 35, 'The invented regulatory line prints 109854.60 USD and 0.002411 USD per outturn litre. Which litres is it levied on, and which is it spread over?', '["Levied on the 45772751.75 bill-of-lading litres, spread over the 45566774.37 outturn litres.", "Levied on the 45566774.37 outturn litres, spread over the 45772751.75 bill-of-lading litres.", "Levied and spread over the 45772751.75 bill-of-lading litres, the one quantity the walk uses.", "Levied and spread over the 45566774.37 outturn litres, since the charge applies to litres sold."]'::jsonb, 0, 'Every per-quantity line is charged on the bill of lading. The column in USD per outturn litre spreads every line over the outturn.'),
  ('supply', 'advanced', 'final', null, 36, 'On the final row of the invented element table, 2100.0000 naira to the dollar, which pair of figures is printed?', '["1433.9982 and 97.1210 naira a litre", "1221.9272 and 75.1996 naira a litre", "1221.9272 and 97.1210 naira a litre", "698.2441 and 97.1210 naira a litre"]'::jsonb, 2, 'The last row of the element table carries 1221.9272 landed and 97.1210 Government beside a price of 1433.9982. 698.2441 is the first row''s landed cost, and 75.1996 the Government row at the invented base rate.'),
  ('supply', 'advanced', 'final', null, 37, 'What do both golden file rows print in their published source column?', '["the published volume correction tables", "the regulation in force", "the engines repository''s findings file", "none"]'::jsonb, 3, 'No coefficient table is shipped and every rate is synthetic, so no figure is checked against a published source. The terminal row adds that its tanks are geometric or the Suite sample.'),
  ('supply', 'advanced', 'final', null, 38, 'With only the invented duty typed 0 and every other invented rate supplied, what does landedCost report for BADAGRY?', '["complete false, total 25114857.82 USD", "complete true, total 26513943.86 USD", "complete true, total 25114857.82 USD", "complete false, total 24774210.79 USD"]'::jsonb, 2, 'A rate typed 0 is a rate. The blank duty prints the same total with complete false and Import duty missing.'),
  ('supply', 'advanced', 'final', null, 39, 'Which recipient does the invented bridging or equalisation element pay in PUMP_TEMPLATE?', '["Chain", "Government", "Terminal", "Unattributed"]'::jsonb, 0, 'Bridging''s recipient is Chain, and the grouping reports 24.5000 naira a litre against it. Unattributed appears only when the course removes that recipient.'),
  ('supply', 'advanced', 'final', null, 40, '34000 tonnes read 40476.190 m3 through cargoQuantities. Which PRODUCT_REFERENCE density was used?', '["745 kg/m3, the PMS row", "800 kg/m3, the DPK row", "840 kg/m3, the AGO row", "960 kg/m3, the HFO row"]'::jsonb, 2, 'The density sweep prints 40476.190 m3 at 840 kg/m3, AGO. PMS at 745 reads 45637.584 m3, DPK at 800 reads 42500.000 m3 and HFO at 960 reads 35416.667 m3.'),
